// The All airports table's market columns: generated, fresh, and honest.
//
//   node tools/airport-markets-test.mjs
//
// packages/engine/src/data/airportMarkets.js is generated by tools/generate-airport-markets.mjs
// (summing 2,134 airports against each other is too slow for a tab to do on
// open). This suite recomputes the whole table and fails if it is stale, then
// checks the in-game figure against the engine's own per-pair functions.
//
// If it fails with "stale": run   node tools/generate-airport-markets.mjs

import assert from 'node:assert/strict';
import { AIRPORTS } from '../src/data/airports.js';
import { AIRPORT_MARKETS, GROWTH_BUCKETS } from '../src/data/airportMarkets.js';
import {
  computeAirportMarkets, growthBuckets, airportMarketNow,
} from '../src/utils/airportMarket.js';
import {
  baseCityPairDemand, cargoCityPairDemand, pairDemandGrowth, setEraStartYear,
} from '../src/utils/market.js';

let passed = 0, failed = 0;
function test(name, fn) {
  try { fn(); console.log(`  ✓ ${name}`); passed++; }
  catch (e) { console.log(`  ✗ ${name}\n      ${(e.stack || e.message).split('\n').slice(0, 4).join('\n      ')}`); failed++; }
}
const REGEN = 'run: node tools/generate-airport-markets.mjs';

console.log('\nAirport market table (Airports → All airports)\n');

test('one row per airport in the game, and no others', () => {
  const codes = new Set(AIRPORTS.map(a => a.code));
  const missing = [...codes].filter(c => !AIRPORT_MARKETS[c]);
  const extra = Object.keys(AIRPORT_MARKETS).filter(c => !codes.has(c));
  assert.deepEqual({ missing, extra }, { missing: [], extra: [] }, `stale — ${REGEN}`);
});

test('growth buckets match the demand-growth table', () => {
  assert.deepEqual(GROWTH_BUCKETS, growthBuckets(), `stale — ${REGEN}`);
});

test('every row matches a fresh computation (the table is not stale)', () => {
  const fresh = computeAirportMarkets(undefined, GROWTH_BUCKETS);
  const diff = AIRPORTS.map(a => a.code)
    .filter(c => JSON.stringify(fresh[c]) !== JSON.stringify(AIRPORT_MARKETS[c]));
  assert.deepEqual(diff.slice(0, 10), [], `${diff.length} airports out of date — ${REGEN}`);
});

test('a single-airport computation agrees with the full symmetric pass', () => {
  for (const c of ['LHR', 'MEM', 'AAE']) {
    assert.deepEqual(computeAirportMarkets([c], GROWTH_BUCKETS)[c], AIRPORT_MARKETS[c], c);
  }
});

// Σ over every destination of the engine's own pair figures — what the column claims to be.
function bruteForce(o, absWeek) {
  let pax = 0, cargo = 0;
  for (const a of AIRPORTS) {
    if (a.code === o) continue;
    pax += baseCityPairDemand(o, a.code) * pairDemandGrowth(o, a.code, absWeek);
    cargo += cargoCityPairDemand(o, a.code);
  }
  return { pax, cargo };
}
const close = (got, want, tol, what) =>
  assert.ok(Math.abs(got - want) <= Math.max(2, want * tol), `${what}: table ${got}, engine ${Math.round(want)}`);

test('classic world, year 1: the column is the sum of the engine\'s pair markets', () => {
  setEraStartYear(null);
  for (const c of ['LHR', 'JFK', 'DEL', 'MEM', 'AAE']) {
    const want = bruteForce(c, 1), got = airportMarketNow(c, AIRPORT_MARKETS[c], GROWTH_BUCKETS, { absWeek: 1 });
    close(got.pax, want.pax, 0.001, `${c} pax`);
    close(got.cargo, want.cargo, 0.001, `${c} cargo`);
  }
});

test('classic world, year 21: per-country growth is applied exactly, cap included', () => {
  setEraStartYear(null);
  const absWeek = 20 * 52 + 1;
  for (const c of ['LHR', 'DEL', 'BOM', 'NRT', 'LOS']) {
    const want = bruteForce(c, absWeek), got = airportMarketNow(c, AIRPORT_MARKETS[c], GROWTH_BUCKETS, { absWeek });
    close(got.pax, want.pax, 0.001, `${c} pax`);
  }
  const del1 = airportMarketNow('DEL', AIRPORT_MARKETS.DEL, GROWTH_BUCKETS, { absWeek: 1 }).pax;
  const del21 = airportMarketNow('DEL', AIRPORT_MARKETS.DEL, GROWTH_BUCKETS, { absWeek }).pax;
  assert.ok(del21 > del1 * 1.5, 'Delhi (8%/yr) should have grown well past half again in 20 years');
});

test('era world: the era traffic index scales every market (1960 ≪ 2026)', () => {
  setEraStartYear(1960);
  try {
    for (const c of ['LHR', 'ORD']) {
      const want = bruteForce(c, 1);
      const got = airportMarketNow(c, AIRPORT_MARKETS[c], GROWTH_BUCKETS, { absWeek: 1, eraStartYear: 1960 });
      close(got.pax, want.pax, 0.001, `${c} pax (1960)`);
      assert.ok(got.pax < AIRPORT_MARKETS[c].slice(1).reduce((s, x) => s + x, 0) / 3, `${c}: 1960 traffic should be a fraction of today's`);
    }
  } finally { setEraStartYear(null); }
});

test('the biggest markets are the airports you would expect', () => {
  const ranked = AIRPORTS.map(a => [a.code, AIRPORT_MARKETS[a.code].slice(1).reduce((s, x) => s + x, 0)])
    .sort((x, y) => y[1] - x[1]).slice(0, 25).map(([c]) => c);
  for (const c of ['LHR', 'JFK']) assert.ok(ranked.includes(c), `${c} not in the top 25 passenger markets: ${ranked.join(' ')}`);
  const cargoTop = AIRPORTS.map(a => [a.code, AIRPORT_MARKETS[a.code][0]]).sort((x, y) => y[1] - x[1]).slice(0, 40).map(([c]) => c);
  assert.ok(cargoTop.includes('HKG'), `HKG not in the top 40 freight markets: ${cargoTop.join(' ')}`);
});

test('a code missing from the table reads as an empty market, not a crash', () => {
  assert.deepEqual(airportMarketNow('ZZZ', undefined, GROWTH_BUCKETS), { pax: 0, cargo: 0 });
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);
